import os,json,glob,subprocess
R="/srv/projects/jellyfin-server"; p=R+"/.install-tmp/info.json"
d={"info_exists":os.path.isfile(p),"logs":[]}
if os.path.isfile(p):
 try:
  x=json.load(open(p,encoding="utf8"))
  d["info"]={"keys":list(x.keys()),"Version":x.get("Version"),"StartupWizardCompleted":x.get("StartupWizardCompleted"),"server_name_present":bool(x.get("ServerName")),"ProductName":x.get("ProductName")}
 except Exception as e:d["info_error"]=type(e).__name__+":"+str(e)[:100]
